C.Guide.chapters[#C.Guide.chapters+1] = (function() return {["id"]="sleeping-bag-finale",["title"]="Sleeping bag · the dam and the wall",["section"]="Leveling",["levels"]={20,20},["url"]="https://cohortgaming.com/journey/sleeping-bag-finale",["parts"]={{["id"]="7865d69cb54167ae",["title"]="Badlands → Loch Modan · summon, then run to the dam",["number"]=1,["note"]="Carry Wet Job from the Stonetalon camp. Take the Fast Travels summon to Kargath flight master in Badlands, then run east to the northbound pass into Loch Modan and continue to Stonewrought Dam. The run is included in travel time. Summon availability and waiting time are unmeasured.",["tasks"]={{["id"]="756315a2cebc40d1",["number"]=1,["kind"]="class_detour",["title"]="Level 20 training due · defer to the next trainer visit",["delivery"]=false,["note"]="Check your level 20 warlock abilities. The next suitable trainer already on this route is Kaal Soulreaper in undercity during the planned level 20 visit. Train the pending levels there. Continue the current outing; this reminder adds no trainer detour. Skip it if already trained.",["optional"]=false,["level"]=20,["point"]={["zone"]="the-barrens",["zoneName"]="The Barrens",["mapId"]=1413,["x"]=35.3,["y"]=27.9,["label"]="Seereth Stonebreak",["approach"]=false},["webStop"]=1},{["id"]="4f0d89403f00c162",["number"]=2,["kind"]="summons",["title"]="Arrange an in-game summon · Kargath · Badlands flight path",["delivery"]=false,["note"]="Optional coordination with another player. Copy the Discord invitation if you want to find a summon.",["optional"]=false,["level"]=20,["point"]={["zone"]="badlands",["zoneName"]="Badlands",["mapId"]=1418,["x"]=3.99,["y"]=44.78,["label"]="Gorrik · Kargath flight master",["approach"]=false},["webStop"]=2,["discord"]="https://discord.gg/82Q5qH9Dc"},{["id"]="176ca3d10ac366e2",["number"]=3,["kind"]="objective",["title"]="Carved Figurine",["questTitle"]="Wet Job",["questId"]=79974,["questLevel"]=32,["objectiveIndex"]=0,["target"]="Carved Figurine",["count"]=1,["action"]="interact",["delivery"]=false,["note"]="At Stonewrought Dam, face north toward Wetlands and drop from the top onto the carved dwarf heads. Inspect the Carved Figurine; avoid the Alliance guards.",["optional"]=false,["level"]=20,["point"]={["zone"]="loch-modan",["zoneName"]="Loch Modan",["mapId"]=1432,["x"]=49.4,["y"]=12.9,["label"]="Carved Figurine · Stonewrought Dam",["approach"]=false},["webStop"]=3,["minLevel"]=14,["questGiver"]="Mound of Dirt · northern ledge"},{["id"]="f5007a42ebaca480",["number"]=4,["kind"]="turnin",["title"]="Wet Job",["questTitle"]="Wet Job",["questId"]=79974,["questLevel"]=32,["delivery"]=false,["note"]="Carry Wet Job from the Stonetalon camp. Take the Fast Travels summon to Kargath flight master in Badlands, then run east to the northbound pass into Loch Modan and continue to Stonewrought Dam. The run is included in travel time. Summon availability and waiting time are unmeasured.",["optional"]=false,["level"]=20,["point"]={["zone"]="loch-modan",["zoneName"]="Loch Modan",["mapId"]=1432,["x"]=49.4,["y"]=12.9,["label"]="Carved Figurine · Stonewrought Dam",["approach"]=false},["webStop"]=4,["minLevel"]=14,["questGiver"]="Mound of Dirt · northern ledge",["turnInNpc"]="Carved Figurine · Stonewrought Dam"},{["id"]="9ab9a907090db156",["number"]=5,["kind"]="pickup",["title"]="Eagle’s Fist",["questTitle"]="Eagle’s Fist",["questId"]=79975,["questLevel"]=32,["delivery"]=false,["note"]="After completing Wet Job, click Carved Figurine · Stonewrought Dam to accept Eagle’s Fist on every character.",["optional"]=false,["level"]=20,["point"]={["zone"]="loch-modan",["zoneName"]="Loch Modan",["mapId"]=1432,["x"]=49.4,["y"]=12.9,["label"]="Carved Figurine · Stonewrought Dam",["approach"]=false},["webStop"]=5,["minLevel"]=14,["questGiver"]="Carved Figurine · Stonewrought Dam"},{["id"]="bd2503947ae3d1d7",["number"]=6,["kind"]="hearthstone_use",["title"]="Use Hearthstone · return to Crossroads inn",["delivery"]=false,["note"]="Use the carried hearthstone bind. The guide includes any remaining cooldown; do not rebind on this outing.",["optional"]=false,["level"]=20,["point"]={["zone"]="the-barrens",["zoneName"]="The Barrens",["mapId"]=1413,["x"]=52,["y"]=29.9,["label"]="Crossroads inn",["approach"]=false},["webStop"]=6}}},{["id"]="fe08cf07f26aa4aa",["title"]="Undercity → Tarren Mill · summon, then fly",["number"]=2,["note"]="After the hearth, request the Undercity summon. Use the Tarren Mill flight point learned during Ruins of Lordaeron. Flights are used in the estimate only when both endpoints are marked learned by everyone.",["tasks"]={{["id"]="cd9c26a380e53832",["number"]=7,["kind"]="summons",["title"]="Arrange an in-game summon · Undercity flight path",["delivery"]=false,["note"]="Optional coordination with another player. Copy the Discord invitation if you want to find a summon.",["optional"]=false,["level"]=20,["point"]={["zone"]="undercity",["zoneName"]="Undercity",["mapId"]=1458,["x"]=69.9,["y"]=34.7,["label"]="Michael Garrett · Undercity flight master",["approach"]=false},["webStop"]=7,["discord"]="https://discord.gg/82Q5qH9Dc"},{["id"]="a0f763e662268450",["number"]=8,["kind"]="library_return",["title"]="Library · turn in carried books",["delivery"]=false,["note"]="Give Owen Thadd any new titles you are carrying. Each character earns their own collection credit. Check milestone rewards at 10 books, 20 books (level 20+) and 25 books (level 35+). Do not claim a milestone until you actually have enough unique titles.",["optional"]=true,["level"]=20,["point"]={["zone"]="undercity",["zoneName"]="Undercity",["mapId"]=1458,["x"]=74,["y"]=32.4,["label"]="Owen Thadd · Undercity library",["approach"]=false},["webStop"]=8},{["id"]="c6ee908de38e798b",["number"]=9,["kind"]="training",["title"]="Train level 20 abilities · Kaal Soulreaper",["delivery"]=false,["note"]="During this existing undercity visit, speak to Kaal Soulreaper and learn your available warlock abilities for level 20. Follow the travel steps to the marked trainer, train, then continue with the next route task. Skip abilities already learned. Training duration and cost are unmeasured; no training time is assumed.",["optional"]=false,["level"]=20,["point"]={["zone"]="undercity",["zoneName"]="Undercity",["mapId"]=1458,["x"]=86.21,["y"]=15.93,["label"]="Kaal Soulreaper · warlock trainer",["approach"]=false},["webStop"]=9},{["id"]="74213c138bc6c827",["number"]=10,["kind"]="flight",["title"]="Fly from Undercity to Tarren Mill",["delivery"]=false,["note"]="Mark Undercity and Tarren Mill learned by all characters. The direct route is about 2 min 21 sec with a base fare of 3s 30c per character (Classic duration fallback; Forever beta fare). If either endpoint is unchecked, the planner shows the overland fallback instead.",["optional"]=false,["level"]=20,["point"]={["zone"]="hillsbrad-foothills",["zoneName"]="Hillsbrad Foothills",["mapId"]=1424,["x"]=60.14,["y"]=18.62,["label"]="Zarise · Tarren Mill flight master",["approach"]=false},["webStop"]=10}}},{["id"]="711c7b962bedfae3",["title"]="Thoradin’s Wall · claim the Cozy Sleeping Bag",["number"]=3,["note"]="Approach from the Hillsbrad side. Complete the two object handoffs on the wall; every character receives their own bag. These are travel and climbing quests available at 14, despite their higher quest-level labels.",["tasks"]={{["id"]="809f9345280b927c",["number"]=11,["kind"]="travel",["title"]="Reach the cart at Thoradin’s Wall",["delivery"]=false,["note"]="Follow the road east from Tarren Mill, then skirt Durnholde toward the wall. Use the cart at 87.4, 49.7 to begin the climb.",["optional"]=false,["level"]=20,["point"]={["zone"]="hillsbrad-foothills",["zoneName"]="Hillsbrad Foothills",["mapId"]=1424,["x"]=87.4,["y"]=49.7,["label"]="Thoradin’s Wall · cart approach",["approach"]=false},["webStop"]=11},{["id"]="38a65991fafd81ef",["number"]=12,["kind"]="objective",["title"]="Messenger Bag",["questTitle"]="Eagle’s Fist",["questId"]=79975,["questLevel"]=32,["objectiveIndex"]=0,["target"]="Messenger Bag",["count"]=1,["action"]="interact",["delivery"]=false,["note"]="Approach Thoradin’s Wall from Hillsbrad 87.4, 49.7. Climb the cart, enter the room in the wall and inspect the Messenger Bag on the right.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Messenger Bag · inside Thoradin’s Wall",["approach"]=false},["webStop"]=12,["minLevel"]=14,["questGiver"]="Carved Figurine · Stonewrought Dam"},{["id"]="83390e450305322b",["number"]=13,["kind"]="turnin",["title"]="Eagle’s Fist",["questTitle"]="Eagle’s Fist",["questId"]=79975,["questLevel"]=32,["delivery"]=false,["note"]="Approach from the Hillsbrad side. Complete the two object handoffs on the wall; every character receives their own bag. These are travel and climbing quests available at 14, despite their higher quest-level labels.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Messenger Bag · inside Thoradin’s Wall",["approach"]=false},["webStop"]=13,["minLevel"]=14,["questGiver"]="Carved Figurine · Stonewrought Dam",["turnInNpc"]="Messenger Bag · inside Thoradin’s Wall"},{["id"]="f3151516f6d529cd",["number"]=14,["kind"]="pickup",["title"]="This Must Be The Place",["questTitle"]="This Must Be The Place",["questId"]=79976,["questLevel"]=32,["delivery"]=false,["note"]="After completing Eagle’s Fist, click Messenger Bag · inside Thoradin’s Wall to accept This Must Be The Place on every character.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Messenger Bag · inside Thoradin’s Wall",["approach"]=false},["webStop"]=14,["minLevel"]=14,["questGiver"]="Messenger Bag · inside Thoradin’s Wall"},{["id"]="852992282a21a657",["number"]=15,["kind"]="objective",["title"]="Hastily Rolled-Up Satchel",["questTitle"]="This Must Be The Place",["questId"]=79976,["questLevel"]=32,["objectiveIndex"]=0,["target"]="Hastily Rolled-Up Satchel",["count"]=1,["action"]="interact",["delivery"]=false,["note"]="Inspect the Hastily Rolled-Up Satchel immediately below the Messenger Bag. Each character completes the interaction for their own Cozy Sleeping Bag.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Hastily Rolled-Up Satchel · below Messenger Bag",["approach"]=false},["webStop"]=15,["minLevel"]=14,["questGiver"]="Messenger Bag · inside Thoradin’s Wall"},{["id"]="3fe1d323d627c702",["number"]=16,["kind"]="turnin",["title"]="This Must Be The Place",["questTitle"]="This Must Be The Place",["questId"]=79976,["questLevel"]=32,["delivery"]=false,["note"]="Approach from the Hillsbrad side. Complete the two object handoffs on the wall; every character receives their own bag. These are travel and climbing quests available at 14, despite their higher quest-level labels.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Hastily Rolled-Up Satchel · below Messenger Bag",["approach"]=false},["webStop"]=16,["minLevel"]=14,["questGiver"]="Messenger Bag · inside Thoradin’s Wall",["turnInNpc"]="Hastily Rolled-Up Satchel · below Messenger Bag"},{["id"]="b34cf4529d549ac2",["number"]=17,["kind"]="rest",["title"]="Use your Cozy Sleeping Bag · rest for three minutes",["delivery"]=false,["note"]="Unroll the bag (15 seconds), then remain in it for three minutes to gain three Well-Rested stacks. ForeverChanges reports a 3% quest/kill XP bonus for two hours and a one-hour item cooldown. The guide counts this rest time but does not multiply future XP by an assumed buff uptime. Student Fodder is food in Forever, not a rested-XP award.",["optional"]=false,["level"]=20,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=22.4,["y"]=24.2,["label"]="Hastily Rolled-Up Satchel · below Messenger Bag",["approach"]=false},["webStop"]=17},{["id"]="c185629a2d42b69a",["number"]=18,["kind"]="hearthstone_use",["title"]="Take a learned flight · Crossroads inn",["delivery"]=false,["note"]="Use the carried hearthstone bind. The guide includes any remaining cooldown; do not rebind on this outing.",["optional"]=false,["level"]=20,["point"]={["zone"]="the-barrens",["zoneName"]="The Barrens",["mapId"]=1413,["x"]=52,["y"]=29.9,["label"]="Crossroads inn",["approach"]=false},["webStop"]=18}}}}} end)()
