C.Guide.chapters[#C.Guide.chapters+1] = (function() return {["id"]="shadowfang-keep-route",["title"]="Shadowfang Keep [D]",["section"]="Leveling",["levels"]={24,24},["url"]="https://cohortgaming.com/journey/shadowfang-keep-route",["parts"]={{["id"]="790cb70ec8e38ae2",["title"]="Undercity → Sepulcher · collect the Shadowfang quests",["number"]=1,["note"]="Collect all three Horde assignments before entering the keep. Warlocks bring The Orb of Soran’ruk from the Taurajo visit; its Blackfathom half comes later.",["tasks"]={{["id"]="895dbcdfb6c7cfca",["number"]=1,["kind"]="class_detour",["title"]="Level 24 training due · defer to the next trainer visit",["delivery"]=false,["note"]="Check your level 24 warlock abilities. The next suitable trainer already on this route is Kaal Soulreaper in undercity during the planned level 24 visit. Train the pending levels there. Continue the current outing; this reminder adds no trainer detour. Skip it if already trained.",["optional"]=false,["level"]=24,["point"]={["zone"]="the-barrens",["zoneName"]="The Barrens",["mapId"]=1413,["x"]=65.84,["y"]=43.86,["label"]="Mahren Skyseer",["approach"]=false},["webStop"]=1},{["id"]="7b1b745264f0f6a6",["number"]=2,["kind"]="summons",["title"]="Arrange an in-game summon · Undercity flight path",["delivery"]=false,["note"]="Optional coordination with another player. Copy the Discord invitation if you want to find a summon.",["optional"]=false,["level"]=24,["point"]={["zone"]="undercity",["zoneName"]="Undercity",["mapId"]=1458,["x"]=69.9,["y"]=34.7,["label"]="Undercity flight master",["approach"]=false},["webStop"]=2,["discord"]="https://discord.gg/82Q5qH9Dc"},{["id"]="8ac19596c4a8e40e",["number"]=3,["kind"]="pickup",["title"]="The Book of Ur",["questTitle"]="The Book of Ur",["questId"]=1013,["questLevel"]=26,["delivery"]=false,["note"]="Collect all three Horde assignments before entering the keep. Warlocks bring The Orb of Soran’ruk from the Taurajo visit; its Blackfathom half comes later.",["option