C.Guide.chapters[#C.Guide.chapters+1] = (function() return {["id"]="arathi-highlands",["title"]="Arathi · Hammerfall and binding stones",["section"]="Leveling",["levels"]={37,38},["url"]="https://cohortgaming.com/journey/arathi-highlands",["parts"]={{["id"]="386e7ff96057d78d",["title"]="Hammerfall · set your hearth and learn the flight path",["number"]=1,["note"]="Establish Hammerfall as the return hub before the chapter’s quest circuits.",["tasks"]={{["id"]="4e7aebde614f5115",["number"]=1,["kind"]="hearthstone",["title"]="Set Hearthstone · Innkeeper Adegwa",["action"]="hearthstone_bind",["delivery"]=false,["note"]="Binding does not reset the one-hour Hearthstone cooldown.",["optional"]=false,["level"]=37,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=73.84,["y"]=32.46,["label"]="Innkeeper Adegwa",["approach"]=false},["webStop"]=1},{["id"]="7f79e773dd4ad5b2",["number"]=2,["kind"]="flight_path",["title"]="Learn flight path · Urda",["action"]="flight_path",["delivery"]=false,["note"]="All party members learn this flight point before using it. Flight duration and fare remain unmeasured unless verified separately.",["optional"]=false,["level"]=37,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=73.02,["y"]=32.7,["label"]="Urda",["approach"]=false},["webStop"]=2}}},{["id"]="c1ad77ca4f76f6b8",["title"]="Riverglades: the western swamp (Incomplete)",["number"]=2,["note"]="We do not yet have a full quest catalog for Riverglades. This chapter covers only the western swamp quests currently recorded and is not a complete leveling route. More quests and routing will be added as they are researched.",["tasks"]={{["id"]="ac8f6e5552e8339b",["number"]=3,["kind"]="class_detour",["title"]="Riverglades: the western swamp (Incomplete)",["delivery"]=false,["note"]="We do not yet have a full quest catalog for Riverglades. This chapter covers only the western swamp quests currently recorded and is not a complete leveling route. More quests and routing will be added as they are researched.",["optional"]=true,["level"]=37,["point"]={["zone"]="arathi-highlands",["zoneName"]="Arathi Highlands",["mapId"]=1417,["x"]=73.02,["y"]=32.7,["label"]="Urda",["approach"]=false},["webStop"]=3}}},{["id"]="155025d7bce4b63f",["title"]="Undercity → Tarren Mill → Hammerfall",["number"]=3,["note"]="Frostmaw is carried from the Thousand Needles Thunder Bluff visit. If you completed the hunt alongside Helcular’s Flame of Uzel in optional Hillsbrad Part 3, skip the cave here. Otherwise complete it on this Alterac crossing. Carry the mane for the next capital visit.",["tasks"]={{["id"]="5de9ad41bffb2e4a",["number"]=4,["kind"]="pickup",["title"]="The Hammer May Fall",["questTitle"]="The Hammer May Fall",["questId"]=676,["questLevel"]=32,["delivery"]=false,["note"]="Frostmaw is carried from the Thousand Needles Thunder Bluff visit. If you completed the hunt alongside Helcular’s Flame of Uzel in optional Hillsbrad Part 3, skip the cave here. Otherwise complete it on this Alterac crossing. Carry the mane for the next capital visit.",["optional"]=false,["level"]=37,["point"]={["zone"]="hillsbrad-foothills",["zoneName"]="Hillsbrad Foothills",["mapId"]=1424,["x"]=61.87,["y"]=19.57,["label"]="Tallow",["approach"]=false},["webStop"]=4,["minLevel"]=30,["questGiver"]="Tallow"},{["id"]="5bacd1be8285bc2d",["number"]=5,["kind"]="objective",["title"]="Frostmaw's Mane",["questTitle"]="Frostmaw",["questId"]=1136,["questLevel"]=37,["objectiveIndex"]=0,["target"]="Frostmaw's Mane",["count"]=1,["action"]="use_item_then_kill_and_loot",["delivery"]=false,["note"]="During the Alterac crossing, get a Fresh Carcass from a nearby mountain lion just before the hunt; it expires after 30 minutes. Clear the yeti cave at 37.5, 66.2, use the carcass at the Flame of Uzel, then kill Frostmaw and collect the mane. Carry the reward back on the next scheduled Thunder Bluff visit.",["optional"]=false,["level"]=37,["point"]={["