C.Guide.chapters[#C.Guide.chapters+1] = (function() return {["id"]="razorfen-downs-route",["title"]="Razorfen Downs [D]",["section"]="Leveling",["levels"]={41,41},["url"]="https://cohortgaming.com/journey/razorfen-downs-route",["parts"]={{["id"]="abb5a82a9417b65b",["title"]="Warlock · Orb of Orahil · optional class journey",["number"]=1,["note"]="Choose one acolyte path, then capture that demon in Desolace. Do not route both Felhound and Infernal alternatives as compulsory quests. Combine Tabetha with Dustwallow and the return reward with Ratchet.",["tasks"]={{["id"]="31ae0ab54aa11f1a",["number"]=1,["kind"]="class_detour",["title"]="Warlock · Orb of Orahil",["delivery"]=false,["note"]="Horde warlocks begin with Kaal Soulreaper in Undercity at level 35. Carry the fragments assignment while completing one acolyte’s shard quest, then return to Menara. Continue through Tabetha’s cleansing and the Ratchet reward.",["optional"]=true,["level"]=41,["point"]={["zone"]="badlands",["zoneName"]="Badlands",["mapId"]=1418,["x"]=42.22,["y"]=52.69,["label"]="Martek the Exiled",["approach"]=false},["webStop"]=1}}},{["id"]="093852e69f04107f",["title"]="Razorfen Downs · exterior",["number"]=2,["note"]="Carry Bring the End from Undercity. The RFK scroll chain must already unlock #6521.",["tasks"]={{["id"]="5204fc8977ec5ec1",["number"]=2,["kind"]="summons",["title"]="Arrange an in-game summon · Undercity flight path",["delivery"]=false,["note"]="Optional coordination with another player. Copy the Discord invitation if you want to find a summon.",["optional"]=false,["level"]=41,["point"]={["zone"]="undercity",["zoneName"]="Undercity",["mapId"]=1458,["x"]=69.9,["y"]=34.7,["label"]="Undercity flight master",["approach"]=false},["webStop"]=2,["discord"]="https://discord.gg/82Q5qH9Dc"},{["id"]="956f6de7530bcac9",["number"]=3,["kind"]="pickup",["title"]="Bring the End",["questTitle"]="Bring the End",["questId"]=3341,["questLevel"]=42,["delivery"]=false,["note"]="Carry Bring the End from Under