C.Guide.chapters[#C.Guide.chapters+1] = (function() return {["id"]="linken",["title"]="Linken · the elixir and the grave",["section"]="Leveling",["levels"]={57,57},["url"]="https://cohortgaming.com/journey/linken",["parts"]={{["id"]="49709b6cb9dae1da",["title"]="Feralas · Gregan, bait and Evoroot",["number"]=1,["note"]="Donova’s elixir assignment is already in the log. Fly from Everlook to Camp Mojache, run to Gregan for bait, collect Evoroot behind Miblon, then return to Gregan for the elixir. This prerequisite trip cannot be replaced by picking up the later quests early.",["tasks"]={{["id"]="6370ea9147160e83",["number"]=1,["kind"]="flight",["title"]="Fly to Camp Mojache · the Videre Elixir",["delivery"]=false,["note"]="Use the learned flight connection. The approach to the flight master, recorded flight duration and onward run are included; if the connection is unavailable, the guide shows the overland fallback.",["optional"]=false,["level"]=57,["point"]={["zone"]="feralas",["zoneName"]="Feralas",["mapId"]=1444,["x"]=75.45,["y"]=44.36,["label"]="Shyn",["approach"]=false},["webStop"]=1},{["id"]="c2b194d3273986a9",["number"]=2,["kind"]="shopping",["title"]="Buy Bait from Gregan",["delivery"]=false,["note"]="Buy bait for every character before going north to Miblon.",["optional"]=false,["level"]=57,["point"]={["zone"]="feralas",["zoneName"]="Feralas",["mapId"]=1444,["x"]=45.12,["y"]=25.57,["label"]="Gregan Brewspewer",["approach"]=false},["webStop"]=2},{["id"]="c0698cf741b883c0",["number"]=3,["kind"]="travel",["title"]="Distract Miblon and collect Evoroot",["delivery"]=false,["note"]="Use the bait to draw Miblon away. Collect Evoroot for every character, then trade it to Gregan.",["optional"]=false,["level"]=57,["point"]={["zone"]="feralas",["zoneName"]="Feralas",["mapId"]=1444,["x"]=44.54,["y"]=10.13,["label"]="Evoroot behind Miblon",["approach"]=false},["webStop"]=3},{["id"]="03453747a81c2da7",["number"]=4,["kind"]="objective",["title"]="Videre Elixir",["questTitle"]="The Videre Elixir",["questId"]=3909,["questLevel"]=52,["objectiveIndex"]=0,["target"]="Videre Elixir",["count"]=1,["action"]="collect",["delivery"]=false,["note"]="Buy Bait from Gregan in Feralas, distract Miblon and collect Evoroot behind him. Return the Evoroot to Gregan for Videre Elixir, then take it to Donova. The repeatable exchange provides the required item but no extra quest XP is counted.",["optional"]=false,["level"]=57,["point"]={["zone"]="feralas",["zoneName"]="Feralas",["mapId"]=1444,["x"]=45.12,["y"]=25.57,["label"]="Gregan Brewspewer",["approach"]=false},["webStop"]=4,["minLevel"]=47,["questGiver"]="Donova Snowden"}}},{["id"]="a675efc6e3c82925",["title"]="Donova → Gadgetzan · deliver the elixir and meet at the grave",["number"]=2,["note"]="Return to the Everlook bind if the hearthstone is ready; otherwise use the learned flight. Visit Donova before flying south. Meet at the Grave takes place at Gadgetzan, not at Donova’s location.",["tasks"]={{["id"]="67a789cc0e1bab2c",["number"]=5,["kind"]="hearthstone_use",["title"]="Use Hearthstone · return to Innkeeper Vizzie",["delivery"]=false,["note"]="Use the existing Everlook bind only when ready; otherwise take the learned flight. The cooldown and approach to Donova are included.",["optional"]=false,["level"]=57,["point"]={["zone"]="winterspring",["zoneName"]="Winterspring",["mapId"]=1452,["x"]=61.36,["y"]=38.83,["label"]="Everlook inn",["approach"]=false},["webStop"]=5},{["id"]="fc9891c145b366dd",["number"]=6,["kind"]="turnin",["title"]="The Videre Elixir",["questTitle"]="The Videre Elixir",["questId"]=3909,["questLevel"]=52,["delivery"]=false,["note"]="Return to the Everlook bind if the hearthstone is ready; otherwise use the learned flight. Visit Donova before flying south. Meet at the Grave takes place at Gadgetzan, not at Donova’s location.",["optional"]=false,["level"]=57,["point"]={["zone"]="winterspring",["zoneName"]="Winterspring",["mapId"]=1452,["x"]=31.27,["y"]=45.16,["label"]="Donova Snowden